import json,pathlib,collections,hashlib,sys
sys.stdout.reconfigure(encoding='utf-8')
H=pathlib.Path(__file__).resolve().parent
S=json.loads((H.parent/'source.json').read_text(encoding='utf-8'))
SID,REV=S['source_id'],S['revision']
N=[json.loads(l) for l in (H/'chapter-notes.jsonl').read_text(encoding='utf-8').splitlines()]
M={int(n['chapter_id'][3:]):n for n in N}
assert len(N)==266 and all(n['full_text_read'] for n in N)
def write(name,value):
 p=H/name;assert p.parent.resolve()==H
 p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n' if not isinstance(value,str) else value,encoding='utf-8')
def E(ids,kind='fact'):
 return [dict(source_id=SID,revision=REV,chapter_id=M[i]['chapter_id'],start_line=M[i]['start_line'],end_line=M[i]['end_line'],claim_kind=kind) for i in sorted(set(ids))]
def O(t,k):return f'{SID}/full-20261025/vol05/{t}/{k}'
cards=[];chars={};scenes={};patterns={}
def card(t,k,title,content,refs):
 x=dict(asset_type=t,scope='reusable-pattern' if t=='pattern' else 'source-analysis',title=title,origin_key=O(t,k),tags=['作者:失落叶','作品:网游之天下无双','卷:5','状态:待审阅'],content=content,evidence=E(refs),user_notes='',favorite=False,review_status='draft')
 cards.append(x);return x
def C(k,title,goal,limits,relation,decisions,changes,refs):
 content=dict(summary=changes,goal=goal,limits=limits,relationship_direction=relation,decisions=decisions,changes=changes,knowledge_boundary='仅本卷时点。现场/系统/共享画面/角色自述/传闻分别见逐章笔记；前四卷未亲读，未借纵横同名人物生平，不预写卷六以后。')
