def SC(k,title,refs,people,goal,obstacle,choice,consequence,change,why,fail):
 content=dict(summary=consequence,goal=goal,obstacle=obstacle,choice=choice,consequence=consequence,state_change=change,why_it_works=why,applicability='研究机制须重造人物、规则与利益，不直接搬运本场景。',failure_mode=fail,claim_kind='synthesis')
 scenes[k]=card('scene',k,title,content,refs)
 scenes[k]['_characters']=people
def P(k,title,scene_keys,steps,applicable,fail,transform):
 refs=sorted({int(e['chapter_id'][3:]) for s in scene_keys for e in scenes[s]['evidence']})
 content=dict(summary=title,causal_steps=steps,applicability=applicable,failure_mode=fail,originality_transform=transform,derived_from_origin_keys=[O('scene',x) for x in scene_keys],boundary='研究者抽象，不是用户审美定案或原创世界设定；不能把人物的民族贬辞、物化和牺牲美化自动迁移。')
